CREATE TABLE subscription_state_history(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,state text NOT NULL,previous_state text,observed_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE subscription_state_history ENABLE ROW LEVEL SECURITY;ALTER TABLE subscription_state_history FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON subscription_state_history USING(workspace_id=nullif(current_setting('app.workspace_id',true),'')::uuid) WITH CHECK(workspace_id=nullif(current_setting('app.workspace_id',true),'')::uuid);
CREATE TABLE platform_reporting_epoch(started_at timestamptz NOT NULL DEFAULT now());INSERT INTO platform_reporting_epoch DEFAULT VALUES;
DO $$ DECLARE tenant uuid;BEGIN FOR tenant IN SELECT DISTINCT workspace_id FROM workspace_access LOOP PERFORM set_config('app.workspace_id',tenant::text,true);INSERT INTO subscription_state_history(workspace_id,state) SELECT workspace_id,state FROM subscriptions;END LOOP;END $$;
CREATE FUNCTION capture_subscription_state() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ BEGIN IF TG_OP='INSERT' THEN INSERT INTO subscription_state_history(workspace_id,state) VALUES(NEW.workspace_id,NEW.state);ELSIF OLD.state IS DISTINCT FROM NEW.state THEN INSERT INTO subscription_state_history(workspace_id,state,previous_state) VALUES(NEW.workspace_id,NEW.state,OLD.state);END IF;RETURN NEW;END $$;
CREATE TRIGGER subscription_state_capture AFTER INSERT OR UPDATE ON subscriptions FOR EACH ROW EXECUTE FUNCTION capture_subscription_state();
ALTER FUNCTION platform_snapshot(text) RENAME TO platform_snapshot_before_reporting;
CREATE FUNCTION platform_snapshot(actor text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE base jsonb;tenant record;queue_rows jsonb:='[]';mrr jsonb;queue jsonb;oldest timestamptz;candidate timestamptz;epoch timestamptz;cancelled integer:=0;active_start integer:=0;n integer;missing integer;known integer;
BEGIN
 base:=platform_snapshot_before_reporting(actor);SELECT min(started_at) INTO epoch FROM platform_reporting_epoch;
 SELECT coalesce(jsonb_agg(to_jsonb(x)),'[]') INTO mrr FROM (SELECT upper(t->'subscription'->>'currency') AS currency,sum((t->'subscription'->>'monthlyAmount')::numeric) AS "monthlyAmount",count(*)::int AS subscriptions FROM jsonb_array_elements(base->'tenants') t WHERE t->'subscription'->>'state'='active' AND t->'subscription'->>'monthlyAmount' IS NOT NULL AND t->'subscription'->>'currency' ~ '^[A-Za-z]{3}$' GROUP BY 1)x;
 SELECT count(*) FILTER(WHERE t->'subscription'->>'state'='active' AND (t->'subscription'->>'monthlyAmount' IS NULL OR coalesce(t->'subscription'->>'currency','') !~ '^[A-Za-z]{3}$')),count(*) FILTER(WHERE t->'subscription'->>'state'='active' AND t->'subscription'->>'monthlyAmount' IS NOT NULL AND t->'subscription'->>'currency' ~ '^[A-Za-z]{3}$') INTO missing,known FROM jsonb_array_elements(base->'tenants')t;
 FOR tenant IN SELECT value FROM jsonb_array_elements(base->'tenants') LOOP
  PERFORM set_config('app.workspace_id',tenant.value->>'id',true);
  SELECT queue_rows||coalesce(jsonb_agg(to_jsonb(x)),'[]') INTO queue_rows FROM (SELECT state,count(*)::int count FROM notification_outbox GROUP BY state)x;
  SELECT min(created_at) INTO candidate FROM notification_outbox WHERE state IN ('pending','retry');IF oldest IS NULL OR candidate<oldest THEN oldest:=candidate;END IF;
  SELECT CASE WHEN EXISTS(SELECT 1 FROM subscription_state_history WHERE observed_at>=now()-interval '30 days' AND previous_state='active' AND state IN ('canceled','cancelled')) THEN 1 ELSE 0 END INTO n;cancelled:=cancelled+n;
  SELECT count(*) INTO n FROM (SELECT state FROM subscription_state_history WHERE observed_at<=now()-interval '30 days' ORDER BY observed_at DESC,id DESC LIMIT 1)x WHERE state='active';active_start:=active_start+n;
 END LOOP;
 SELECT coalesce(jsonb_agg(to_jsonb(x)),'[]') INTO queue FROM (SELECT value->>'state' state,sum((value->>'count')::integer)::integer count FROM jsonb_array_elements(queue_rows) GROUP BY 1)x;
 RETURN base||jsonb_build_object('metrics',jsonb_build_object('mrr',mrr,'mrrState',CASE WHEN known=0 THEN 'unconfigured' WHEN missing>0 THEN 'partial' ELSE 'observed' END,'churn',jsonb_build_object('state',CASE WHEN epoch>now()-interval '30 days' THEN 'insufficient_history' ELSE 'observed' END,'ratePercent',CASE WHEN epoch<=now()-interval '30 days' AND active_start>0 THEN 100.0*cancelled/active_start ELSE NULL END,'activeAtStart',CASE WHEN epoch<=now()-interval '30 days' THEN active_start ELSE NULL END,'cancelled',cancelled,'windowDays',30,'historyStartedAt',epoch),'queue',queue,'queueOldestPendingAt',oldest));
END $$;
ALTER FUNCTION platform_mutation(text,text,text,jsonb) RENAME TO platform_mutation_before_reporting;
CREATE FUNCTION platform_mutation(actor text,action text,identifier text,payload jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE targets uuid[];target uuid;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM auth_user WHERE id=actor AND "platformAdmin") THEN RAISE EXCEPTION 'Platform access denied' USING ERRCODE='42501';END IF;
 IF action<>'flag' THEN PERFORM platform_mutation_before_reporting(actor,action,identifier,payload);RETURN;END IF;
 IF identifier !~ '^[a-z][a-z0-9._-]{0,79}$' OR jsonb_typeof(payload->'enabled')<>'boolean' OR (payload->>'rollout')::numeric NOT BETWEEN 0 AND 100 OR (payload->>'rollout')::numeric<>trunc((payload->>'rollout')::numeric) OR jsonb_typeof(coalesce(payload->'workspaceIds','[]'))<>'array' OR jsonb_array_length(coalesce(payload->'workspaceIds','[]'))>1000 THEN RAISE EXCEPTION 'Invalid flag';END IF;
 SELECT coalesce(array_agg(DISTINCT value::uuid),'{}') INTO targets FROM jsonb_array_elements_text(coalesce(payload->'workspaceIds','[]'));
 FOREACH target IN ARRAY targets LOOP PERFORM set_config('app.workspace_id',target::text,true);IF NOT EXISTS(SELECT 1 FROM workspaces WHERE id=target) THEN RAISE EXCEPTION 'Target workspace unavailable';END IF;END LOOP;
 INSERT INTO feature_flags(key,enabled,rollout,workspace_ids) VALUES(identifier,(payload->>'enabled')::boolean,(payload->>'rollout')::integer,targets) ON CONFLICT(key) DO UPDATE SET enabled=EXCLUDED.enabled,rollout=EXCLUDED.rollout,workspace_ids=EXCLUDED.workspace_ids;
END $$;
REVOKE ALL ON FUNCTION capture_subscription_state(),platform_snapshot(text),platform_mutation(text,text,text,jsonb) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION platform_snapshot_before_reporting(text),platform_mutation_before_reporting(text,text,text,jsonb) FROM watchtower_app;
GRANT EXECUTE ON FUNCTION platform_snapshot(text),platform_mutation(text,text,text,jsonb) TO watchtower_app;

CREATE OR REPLACE FUNCTION read_status_page(page_slug text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE item record; page record; result jsonb; BEGIN SELECT * INTO item FROM product_public_index WHERE kind='status_pages' AND lookup=page_slug; IF NOT FOUND THEN RETURN NULL; END IF; PERFORM set_config('app.workspace_id',item.workspace_id::text,true); SELECT p.* INTO page FROM status_pages p JOIN workspaces w ON w.id=p.workspace_id WHERE p.id=item.resource_id AND p.published AND NOT w.suspended; IF NOT FOUND THEN RETURN NULL; END IF; SELECT jsonb_build_object('id',page.id,'name',page.name,'slug',page.slug,'config',page.config,'passwordHash',page.password_hash,'components',coalesce((SELECT jsonb_agg(jsonb_build_object('id',m.id,'name',m.name,'duration_ms',CASE WHEN coalesce((page.config->>'showResponseTime')::boolean,true) THEN (SELECT r.duration_ms FROM check_results r WHERE r.monitor_id=m.id AND r.workspace_id=m.workspace_id ORDER BY r.observed_at DESC LIMIT 1) ELSE NULL END,'observed_at',(SELECT r.observed_at FROM check_results r WHERE r.monitor_id=m.id AND r.workspace_id=m.workspace_id ORDER BY r.observed_at DESC LIMIT 1),'state',CASE WHEN m.paused THEN 'paused' ELSE m.state END)) FROM status_components c JOIN monitors m ON m.id=c.monitor_id AND m.workspace_id=c.workspace_id WHERE c.page_id=page.id),'[]'::jsonb),'updates',coalesce((SELECT jsonb_agg(jsonb_build_object('title',u.title,'body',u.body,'created_at',u.created_at)) FROM (SELECT * FROM status_updates WHERE page_id=page.id ORDER BY created_at DESC LIMIT 30)u),'[]'::jsonb)) INTO result; RETURN result; END $$;
CREATE FUNCTION monitor_expected_regions(monitor uuid) RETURNS TABLE(region text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT r.region FROM monitors m CROSS JOIN LATERAL jsonb_array_elements_text(CASE WHEN m.config ? 'privateProbeId' THEN jsonb_build_array((SELECT p.region FROM probes p WHERE p.id=m.config->>'privateProbeId' AND p.workspace_id=m.workspace_id)) ELSE coalesce(m.config->'regions','["local"]'::jsonb) END)r(region) WHERE m.id=monitor AND r.region IS NOT NULL $$;
REVOKE ALL ON FUNCTION monitor_expected_regions(uuid) FROM PUBLIC;GRANT EXECUTE ON FUNCTION monitor_expected_regions(uuid) TO watchtower_app;
